//! B continuous purpose-neutral work-record production. Future delegation is unavailable.
use super::sources::*;use crate::context::Context;use serde_json::{json,Value};
pub fn produce(ctx:&mut Context,sources:&Sources,state:&Value,previous:&Value,trigger:&Value,revision:u64)->Result<Value,String>{
 let mut evidence=Vec::new();for s in sources.values().filter(|s|s["revoked"].as_bool()!=Some(true)){let(a,b)=bounds(s);evidence.push(read(ctx,s,a,b,"VIA_RECORD_PRODUCER")?);}
 let response=ctx.call("dp05_produce_work_record",&json!({"instruction":"Maintain a purpose-neutral source-backed work record from observed public activities and prior adopted state ONLY. No future delegation purpose is known. Return JSON {blocks:[{block_id:string,explanation:string,source_spans:[{source_id:string,revision:number,start_line:number,end_line:number}]}],conditions:[string],unknowns:[string],coverage:[string]}. At most 8 compact reusable blocks. Capture what public results established, qualifications/replacements, conditions/exclusions and unresolved scope. Do not copy Task IDs as explanation or invent future domain plans. Use exact current original spans; prepared/undelivered text is not delivered. Old record is not authority on corrections or access changes.","input":{"observed_trigger":trigger,"current_adopted_state":state,"public_evidence":evidence,"previous_record":previous},"max_tokens":2200}))?;
 let mut blocks=Vec::new();for mut b in array(&response["blocks"]){let spans=array(&b["source_spans"]);if spans.is_empty()||!spans.iter().all(|p|valid_span(p,sources)&&evidence.iter().any(|e|contained(p,e))){ctx.event("PROVENANCE_REJECTED",&json!({"stage":"work_record_publication","block":b}));continue;}
  let mut support=Vec::new();for span in spans{if let Some(p)=evidence.iter().find(|p|contained(&span,p)){let lo=span["start_line"].as_u64().unwrap();let hi=span["end_line"].as_u64().unwrap();let base=p["start_line"].as_u64().unwrap();let mut q=span.clone();q["text"]=json!(p["text"].as_str().unwrap().lines().skip((lo-base)as usize).take((hi-lo+1)as usize).collect::<Vec<_>>().join("\n"));support.push(q);}}b["supporting_passages"]=json!(support);blocks.push(b);
 }
 let r=json!({"record_revision":revision,"status":"PUBLISHED","producer_node":ctx.last_node(),"source_vector":catalog(sources),"blocks":blocks,"conditions":response["conditions"],"unknowns":response["unknowns"],"coverage":response["coverage"]});ctx.event("WORK_RECORD_PUBLICATION",&r);Ok(r)
}
